uniform float speed : 0.0 .. 5.0 = 0.6;
uniform float width : 0.02 .. 1.0 = 0.5;
uniform float sat   : 0.0 .. 1.0 = 1.0;
uniform float val   : 0.0 .. 1.0 = 1.0;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed * 0.25));
}
vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed band = clamp((fixed(1.0) - abs(fract(ang - ph) - fixed(0.5)) * fixed(2.0)) * fixed(1.0) / fixed(width), fixed(0.0), fixed(1.0));
  return hsv2rgb(fract(ang - ph), fixed(sat), fixed(val)) * vec3(band, band, band);
}

uniform float speed : 0.0 .. 5.0 = 0.6;
uniform float width : 0.02 .. 1.0 = 0.5;
uniform float sat   : 0.0 .. 1.0 = 1.0;
uniform float val   : 0.0 .. 1.0 = 1.0;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed * 0.25));
}
vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed frac = fract(ang - ph);
  fixed d = abs(frac - fixed(0.5));
  fixed band = clamp((fixed(0.5) - d) * fixed(2.0) / fixed(width), fixed(0.0), fixed(1.0));
  vec3 c = hsv2rgb(fract(ang - ph), fixed(sat), fixed(val));
  return c * vec3(band, band, band);
}

